(()=>{'use strict';
if(window.__OBRIX_CORRECOES_POS_RENDER_0211)return;window.__OBRIX_CORRECOES_POS_RENDER_0211=true;
let obraChecklistId='',filaVisual=false,saveTimer=null,refreshTimer=null,canal=null,retryTimer=null,ctxCache=null;
const estilo=document.createElement('style');estilo.id='obrix-pos-render-0211-style';estilo.textContent=`@media(max-width:760px){#fmFiltroDataInicio::-webkit-date-and-time-value,#fmFiltroDataFim::-webkit-date-and-time-value{min-width:0!important;padding:0!important;text-align:left!important}#fmFiltroDataInicio::-webkit-calendar-picker-indicator,#fmFiltroDataFim::-webkit-calendar-picker-indicator{margin:0!important;padding:0!important;width:14px!important;min-width:14px!important}}`;
function estiloPorUltimo(){if(estilo.parentNode!==document.head||document.head.lastElementChild!==estilo)document.head.appendChild(estilo)}
function brancoAndamento(){document.querySelectorAll('#obras .obxStatus.andamento,#listaObras .obxStatus.andamento').forEach(el=>{el.style.setProperty('color','#fff','important');el.style.setProperty('-webkit-text-fill-color','#fff','important')})}
function corrigirDatas(){if(innerWidth>760)return;for(const id of ['fmFiltroDataInicio','fmFiltroDataFim']){const el=document.getElementById(id);if(!el)continue;const lab=el.closest('label');if(lab){lab.style.setProperty('min-width','0','important');lab.style.setProperty('overflow','visible','important')}el.style.setProperty('display','block','important');el.style.setProperty('width','100%','important');el.style.setProperty('max-width','100%','important');el.style.setProperty('min-width','0','important');el.style.setProperty('box-sizing','border-box','important');el.style.setProperty('font-size',innerWidth<=430?'10px':'11px','important');el.style.setProperty('letter-spacing','-.2px','important');el.style.setProperty('padding-left','1px','important');el.style.setProperty('padding-right','1px','important');el.style.setProperty('text-indent','0','important')}}
function aplicarVisuais(){filaVisual=false;estiloPorUltimo();brancoAndamento();corrigirDatas();detectarObraModal()}
function agendarVisuais(){if(filaVisual)return;filaVisual=true;requestAnimationFrame(aplicarVisuais)}
function detectarObraModal(){if(!document.querySelector('.checkModalBack')){obraChecklistId='';return}if(obraChecklistId)return;const nome=document.querySelector('.checkModalBack .checkHead .muted')?.textContent?.trim();if(!nome)return;const o=(window.obras||[]).find(x=>String(x.nome||'').trim()===nome);if(o)obraChecklistId=String(o.id)}
function capturarObraChecklist(alvo){const b=alvo?.closest?.('[data-check-open],[onclick*="OBRIX_OBRAS_FIEL.checklist"],[onclick*="OBRIX_CHECKLIST.open"]');if(!b)return;let id=b.dataset?.checkOpen||'';if(!id){const txt=b.getAttribute('onclick')||'';id=(txt.match(/checklist\(['\"]([^'\"]+)['\"]\)/i)||txt.match(/OBRIX_CHECKLIST\.open\?\.\(['\"]([^'\"]+)['\"]\)/i)||[])[1]||''}if(id)obraChecklistId=String(id)}
function mediaAtual(){const ranges=[...document.querySelectorAll('.checkModalBack [data-check-range]')];if(!ranges.length)return null;const soma=ranges.reduce((s,r)=>s+Math.max(0,Math.min(100,Number(r.value||0))),0);return Math.round((soma/ranges.length)*10)/10}
function fmt(p){return Number.isInteger(p)?String(p):p.toLocaleString('pt-BR',{maximumFractionDigits:1})}
function aplicarProgressoLocal(id,p){if(!id||p==null)return;const o=(window.obras||[]).find(x=>String(x.id)===String(id));if(o){o.progresso=p;o.percentual=p;o.percentual_conclusao=p}const safe=(window.CSS&&CSS.escape)?CSS.escape(String(id)):String(id).replace(/"/g,'\\"');const card=document.querySelector(`#listaObras .obxObraCard[data-id="${safe}"]`);if(card){const bar=card.querySelector('.obxStatusLinha .obxBar i'),n=card.querySelector('.obxStatusLinha > b');if(bar)bar.style.width=p+'%';if(n)n.textContent=fmt(p)+'%'}const det=document.querySelector('#listaObras .obxDetalhe');if(det){const bar=det.querySelector('.obxProg .obxBar i'),n=det.querySelector('.obxProg > b');if(bar)bar.style.width=p+'%';if(n)n.textContent=fmt(p)+'%'}try{window.OBRIX_OBRAS_FIEL?.refresh?.()}catch(_){}brancoAndamento()}
async function contexto(){if(ctxCache)return ctxCache;const p=await window.OBRIX_BACKEND?.profile?.();if(!p?.empresa_id)return null;ctxCache={sb:await window.OBRIX_BACKEND.init(),eid:p.empresa_id};return ctxCache}
async function salvarProgresso(){detectarObraModal();const id=obraChecklistId,p=mediaAtual();if(!id||p==null||!navigator.onLine)return;aplicarProgressoLocal(id,p);try{const c=await contexto();if(!c)return;const r=await c.sb.from('obras').update({progresso:p}).eq('empresa_id',c.eid).eq('id',id);if(r.error)throw r.error}catch(e){console.warn('OBRIX: não foi possível salvar o progresso geral agora',e)}}
function agendarSalvar(){clearTimeout(saveTimer);saveTimer=setTimeout(salvarProgresso,520)}
async function atualizarDados(){if(!navigator.onLine||document.hidden)return;try{if(typeof window.OBRIX_REFRESH_ALL==='function')await window.OBRIX_REFRESH_ALL();else if(typeof window.carregar==='function')await window.carregar()}catch(e){console.warn('OBRIX: sincronização será repetida depois',e)}finally{agendarVisuais()}}
function agendarDados(ms=260){clearTimeout(refreshTimer);refreshTimer=setTimeout(atualizarDados,ms)}
function pararCanal(){clearTimeout(retryTimer);retryTimer=null;if(canal){try{canal.unsubscribe?.()}catch(_){}canal=null}}
async function realtime(){if(canal||!navigator.onLine)return;try{const c=await contexto();if(!c)return;let ch=c.sb.channel('obrix-sync-pos-render-'+c.eid);ch=ch.on('postgres_changes',{event:'*',schema:'public',table:'obras',filter:`empresa_id=eq.${c.eid}`},payload=>{const novo=payload?.new;if(novo?.id){const o=(window.obras||[]).find(x=>String(x.id)===String(novo.id));if(o)Object.assign(o,novo);try{window.OBRIX_OBRAS_FIEL?.refresh?.()}catch(_){}try{window.OBRIX_DASH?.paint?.()}catch(_){}agendarVisuais()}else agendarDados(180)});for(const tabela of ['financeiro','funcionarios','diarias','vales','bonus_extras','servicos_extras'])ch=ch.on('postgres_changes',{event:'*',schema:'public',table:tabela,filter:`empresa_id=eq.${c.eid}`},()=>agendarDados(240));canal=ch.subscribe(status=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED'){pararCanal();retryTimer=setTimeout(realtime,1500)}})}catch(e){console.warn('OBRIX: realtime indisponível',e);pararCanal();retryTimer=setTimeout(realtime,1800)}}
document.addEventListener('click',e=>{capturarObraChecklist(e.target);setTimeout(agendarVisuais,0);setTimeout(agendarVisuais,180)},true);
document.addEventListener('input',e=>{if(!e.target.closest?.('[data-check-range]'))return;detectarObraModal();const p=mediaAtual();if(obraChecklistId&&p!=null)aplicarProgressoLocal(obraChecklistId,p)},true);
document.addEventListener('change',e=>{if(!e.target.closest?.('[data-check-range]'))return;detectarObraModal();const p=mediaAtual();if(obraChecklistId&&p!=null)aplicarProgressoLocal(obraChecklistId,p);agendarSalvar()},true);
const root=document.getElementById('app')||document.body;new MutationObserver(agendarVisuais).observe(root,{childList:true,subtree:true});
window.addEventListener('focus',()=>{agendarVisuais();agendarDados(120);realtime()});window.addEventListener('pageshow',()=>{agendarVisuais();agendarDados(120);realtime()});document.addEventListener('visibilitychange',()=>{if(!document.hidden){agendarVisuais();agendarDados(120);realtime()}});window.addEventListener('online',()=>{pararCanal();agendarDados(100);realtime()});window.addEventListener('offline',pararCanal);window.addEventListener('resize',agendarVisuais);
setTimeout(()=>{agendarVisuais();realtime()},350);setTimeout(agendarVisuais,1200);
})();